        ;; interrupts.s
        ;;
        ;; Minimal IM2 table setup for the ROM-loaded Partner first stage. The
        ;; table begins at 0xff00 and supports the even vectors generated by
        ;; Partner peripherals. Unclaimed interrupts return through a safe ISR.
        ;;
        ;; MIT License (see: LICENSE)
        ;; Copyright (C) 2026 Tomaz Stih
        ;;
        ;; 2026-08-10   tstih

        .module interrupts

        .include "partner.inc"

        .globl  interrupt_init
        .globl  interrupt_set
        .globl  interrupt_default_handler
        .globl  _interrupt_init
        .globl  _interrupt_set

        .area   _CODE

        ;; ------------------------------------------------------------
        ;; interrupt_init
        ;; Populate all 128 even IM2 slots with the default handler, select
        ;; IM2, and leave maskable interrupts disabled for device setup.
        ;;
        ;; Returns: nothing
        ;;
        ;; Clobbers: A, B, DE, HL
_interrupt_init::
interrupt_init::
        di
        ld      hl,#PARTNER_IM2_BASE
        ld      de,#interrupt_default_handler
        ld      b,#128
.interrupt_fill:
        ld      (hl),e
        inc     hl
        ld      (hl),d
        inc     hl
        djnz    .interrupt_fill
        ld      a,#(PARTNER_IM2_BASE >> 8)
        ld      i,a
        im      2
        ret

        ;; ------------------------------------------------------------
        ;; interrupt_set
        ;; Install a handler in an even IM2 slot. Odd vectors are rounded down;
        ;; Partner interrupting devices use even vectors.
        ;;
        ;; Arguments:
        ;;   A  = raw interrupt vector
        ;;   DE = handler address
        ;;
        ;; Returns: nothing; interrupts remain disabled
        ;;
        ;; Clobbers: A, HL
_interrupt_set::
interrupt_set::
        di
        and     #0xfe
        ld      l,a
        ld      h,#(PARTNER_IM2_BASE >> 8)
        ld      (hl),e
        inc     hl
        ld      (hl),d
        ret

        ;; ------------------------------------------------------------
        ;; interrupt_default_handler
        ;; Acknowledge and ignore an interrupt from an unclaimed even vector.
        ;;
        ;; Returns: with maskable interrupts enabled
        ;;
        ;; Clobbers: none
interrupt_default_handler::
        ;; The ROM can leave either keyboard PIO port requested under a changing
        ;; vector. Converge both control parsers, disable them, and explicitly
        ;; clear their NEEDED/REQUESTED state before releasing the daisy chain.
        push    af
        ld      a,#PARTNER_PIO_MODE_OUTPUT
        out     (PARTNER_PORT_PIO_A_CTRL),a
        ld      a,#PARTNER_PIO_INT_DISABLE
        out     (PARTNER_PORT_PIO_A_CTRL),a
        ld      a,#PARTNER_PIO_INT_MASK_ALL
        out     (PARTNER_PORT_PIO_A_CTRL),a
        ld      a,#PARTNER_PIO_MODE_OUTPUT
        out     (PARTNER_PORT_PIO_B_CTRL),a
        ld      a,#PARTNER_PIO_INT_DISABLE
        out     (PARTNER_PORT_PIO_B_CTRL),a
        ld      a,#PARTNER_PIO_INT_MASK_ALL
        out     (PARTNER_PORT_PIO_B_CTRL),a
        pop     af
        ei
        reti
